Proceso MayorDeVector
    Dimension numeros[5] Como Entero;
    Definir i Como Entero;
    Definir mayor Como Entero;
    Para i <- 0 Hasta 4 Hacer
        Leer numeros[i];
    FinPara
    mayor <- numeros[0];
    Para i <- 1 Hasta 4 Hacer
        Si numeros[i] > mayor Entonces
            mayor <- numeros[i];
        FinSi
    FinPara
    Escribir mayor;
FinProceso
